"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2766],{12766:e=>{e.exports=JSON.parse('{"slug":"fed-podnyala-stavku-oktyabr-povyshenie","locale":"ru","title":"ФРС подняла ставку до 3,75–4%, а рынок ставит больше 50% на ещё одно повышение уже в октябре","description":"ФРС на прошлой неделе единогласно повысила ставку на четверть пункта, до 3,75–4%. Рынок ставит больше 50% на новое повышение в октябре, а глава ФРБ Миннеаполиса Нил Кашкари объяснил почему: инфляция вышла за пределы нефтяного шока.","blocks":[{"id":"b001","kind":"paragraph","text":"Федеральная резервная система на прошлой неделе подняла ставку на 0,25 процентного пункта, до диапазона 3,75–4%, и голосование было единогласным. В прогнозах, опубликованных вместе с решением, все члены комитета, кроме двух, ждут в этом году ещё как минимум одного повышения на четверть пункта. Рынок фьючерсов называет срок: шанс повышения в октябре оценивается выше 50%, а с вероятностью две трети ставка закончит 2026 год в диапазоне 4–4,25%."},{"id":"b002","kind":"paragraph","text":"Крупные банки уже пересмотрели прогнозы. Экономисты Goldman Sachs в среду написали, что теперь ждут второго повышения на 25 базисных пунктов, хотя раньше считали сентябрьское единственным. Заседание, по их словам, \xabоказалось более ястребиным, чем мы ожидали\xbb, и указали на две вещи: единогласие и формулировку главы ФРС Кевина Уорша, который назвал повышение \xabубранной дозой стимула\xbb. Майкл Гусей из Principal Asset Management считает, что это \xabможет быть не одно-два повышения и всё\xbb, а нечто более существенное, если ФРС всерьёз хочет \xabразрушить спрос\xbb."},{"id":"b003","kind":"paragraph","text":"В воскресенье позицию регулятора объяснил Нил Кашкари в эфире Fox News. \xabДаже если убрать энергию, которая очень волатильна, и убрать еду, инфляция всё ещё слишком высокая\xbb, сказал он. Кашкари поддержал повышение, а на предыдущем заседании был одним из трёх, кто голосовал за него, когда большинство решило ставку не трогать. Его мысль коротко: давление на цены вышло за пределы нефтяного шока от войны в Иране."},{"id":"b004","kind":"paragraph","text":"Почему это различие важно. Когда зимой в квартире открыли окно, счёт за отопление растёт, но проблема не в батарее. Так работает скачок нефти: ставка не добавит танкеров в проливе и на цену бензина напрямую не влияет. Если же при закрытом окне дорожают хлеб, стрижка и аренда, дело в самой квартире. То, что остаётся после вычета энергии и еды, называют \xabбазовой инфляцией\xbb, и именно она, по Кашкари, слишком высока. Против неё ставка работает: дорогой кредит заставляет покупать меньше, и продавцы теряют возможность поднимать ценники."},{"id":"b005","kind":"paragraph","text":"Последствия уже видны на рынке долга. За прошлую неделю стоимость заимствований для правительства США поднялась до максимума с 2007 года, и это тянет за собой кредит для домохозяйств, компаний и других правительств. Госдолг США выше $40 трлн, нефть дороже $100 за баррель. Стратег Эд Ярдени снизил цель по индексу S&P 500 на конец года, опасаясь этой связки: дорогая нефть, дорогие деньги."},{"id":"b006","kind":"paragraph","text":"Для читателя в России канал не прямой, а через доллар и нефть, и они тянут в разные стороны. Высокая ставка в США делает доллар привлекательнее для мирового капитала, и он дорожает, а дорогой доллар это дороже импорт: техника, лекарства, запчасти. Нефть выше $100 при этом поддерживает выручку экспортёров и бюджет, а значит, и рубль. Какой канал перевесит, неизвестно. Ключевая ставка ЦБ считается по российской инфляции, а не по решениям ФРС."},{"id":"b007","kind":"paragraph","text":"Чего пока не знаем: пойдёт ли ФРС в октябре и подтвердят ли следующие данные по ценам слова Кашкари. Рынок видит вероятность, а не факт. Для обычного человека выбор такой. Покупать доллары под новость о ставке значит покупать вместе с рынком, который эту новость уже заложил в цену. Не замечать её тоже дорого: если ФРС идёт в серию повышений, а нефть не перевесит, дорогой доллар становится не эпизодом, а фоном на год, и в цену импорта он протекает с задержкой."}],"sources":[{"label":"https://finance.yahoo.com/economy/policy/article/this-could-be-something-more-substantial-wall-street-braces-for-more-fed-rate-hikes-123400710.html","url":"https://finance.yahoo.com/economy/policy/article/this-could-be-something-more-substantial-wall-street-braces-for-more-fed-rate-hikes-123400710.html"},{"label":"https://finance.yahoo.com/economy/policy/articles/feds-kashkari-says-inflation-goes-150738609.html","url":"https://finance.yahoo.com/economy/policy/articles/feds-kashkari-says-inflation-goes-150738609.html"},{"label":"https://www.reuters.com/business/feds-kashkari-says-inflation-goes-beyond-oil-prices-according-fox-news-interview-2026-09-20","url":"https://www.reuters.com/business/feds-kashkari-says-inflation-goes-beyond-oil-prices-according-fox-news-interview-2026-09-20"},{"label":"https://www.bloomberg.com/news/articles/2026-09-20/fed-s-kashkari-says-inflation-reaching-all-corners-of-us-economy","url":"https://www.bloomberg.com/news/articles/2026-09-20/fed-s-kashkari-says-inflation-reaching-all-corners-of-us-economy"},{"label":"https://www.theguardian.com/business/ng-interactive/2026/sep/20/stock-market-crash-government-bond-yields","url":"https://www.theguardian.com/business/ng-interactive/2026/sep/20/stock-market-crash-government-bond-yields"}],"sourceBodySha256":"4ccdae1c42dfa6caadccaf2dc660d7a7e9e7292252f88121ef27a0488828b560"}')}}]);